use xiom.io;

fn calculate_score(attempts: Int) -> Int {
  let score = (7 - attempts + 1) * 100 / 7;
  if score < 0 { return 0; };
  score
}

fn main() -> Int {
  let secret = 42;
  io.println("Guess a number between 1 and 100!");

  var attempts = 0;
  var won = false;
  var done = false;
  while !done && attempts < 10 {
    let parsed = io.read_int();
    match parsed {
      Ok(guess) => {
        attempts += 1;
        if guess == secret {
          io.println("Correct! Attempts: " + attempts.to_str());
          won = true;
          done = true;
        } else {
          if guess < secret {
            io.println("Too low!");
          } else {
            io.println("Too high!");
          };
        };
      }
      Err(message) => {
        io.println("I could not read that: " + message);
        done = true;
      };
    };
  };

  if won {
    io.println("Score: " + calculate_score(attempts).to_str());
  };
  if !won && attempts >= 10 {
    io.println("Out of attempts! The number was " + secret.to_str() + ".");
  };
  return 0;
}
